query TaxonBreakdown($key: ID!, $datasetKey: ID!) {
  taxonInfo(key: $key, datasetKey: $datasetKey) {
    key: taxonID
    rank: taxonRank
    scientificName
    datasetKey
    checklistBankBreakdown: breakdown(sortByCount: true) {
      id: taxonID
      name: scientificName
      rank: taxonRank
      species
      children: breakdown {
        id: taxonID
        name: scientificName
        rank: taxonRank
        species
        children: breakdown {
          id: taxonID
          name: scientificName
          rank: taxonRank
          species
        }
      }
    }
  }
}
